.emc-control-guide { pointer-events: none; stroke: currentcolor; stroke-width: 1px; stroke-dasharray: 3px, 4px; opacity: 0.28; }
.emc-geometry-handle { cursor: pointer; }
.emc-geometry-move { cursor: move; }
.emc-geometry-nw, .emc-geometry-se { cursor: nwse-resize; }
.emc-geometry-ne, .emc-geometry-sw { cursor: nesw-resize; }
