.stage.is-dragging-text .emc-map-text { cursor: grabbing; }
.emc-label-fva { font-size: calc(10.5px * var(--label-scale)); font-variant-numeric: tabular-nums; font-weight: 650; }
.emc-node-primary { opacity: 1; }
.emc-node-secondary { opacity: 0.78; stroke-width: 1.8px !important; }
